package com.loanops.fincompass;
import com.loanops.fincompass.opportunity.*;import com.loanops.fincompass.simulation.*;import com.loanops.fincompass.twin.*;import org.junit.jupiter.api.Test;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.test.context.*;import org.springframework.test.web.servlet.MockMvc;import org.testcontainers.junit.jupiter.*;import org.testcontainers.postgresql.PostgreSQLContainer;import org.testcontainers.utility.DockerImageName;import java.util.*;import static com.loanops.fincompass.opportunity.OpportunityModels.*;import static org.assertj.core.api.Assertions.*;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
@Testcontainers @SpringBootTest @AutoConfigureMockMvc @ActiveProfiles("fincompass-demo") class OpportunityIntegrationTest {@Container static final PostgreSQLContainer DB=new PostgreSQLContainer(DockerImageName.parse("postgres:17.11-alpine"));@DynamicPropertySource static void props(DynamicPropertyRegistry r){r.add("spring.datasource.url",DB::getJdbcUrl);r.add("spring.datasource.username",DB::getUsername);r.add("spring.datasource.password",DB::getPassword);r.add("fincompass.open-banking.encryption-key",()->Base64.getEncoder().encodeToString(new byte[32]));}
 @Autowired OpportunityService opportunities;@Autowired ScenarioService scenarios;@Autowired FinancialTwinStore twins;@Autowired JdbcTemplate jdbc;@Autowired MockMvc http;static final String OWNER="golden-homebuyer";
 @Test void goldenHomeCreatesTwoEvidenceBasedReviewEventsIdempotently(){scenarios.createHome(OWNER,ScenarioExamples.golden(twins.latest(OWNER).financialSnapshotId()));var first=opportunities.detect(OWNER);assertThat(first).extracting(Event::type).contains(Type.LIQUIDITY_RISK,Type.DEBT_BURDEN_WARNING);assertThat(first).allSatisfy(e->{assertThat(e.ruleVersion()).isEqualTo("OPPORTUNITY_V1");assertThat(e.status()).isEqualTo("ACTIVE");assertThat(e.scenarioId()).isNotNull();assertThat(e.evidence().actual()).isNotNull();});int afterFirst=jdbc.queryForObject("SELECT count(*) FROM loanops.opportunity_event",Integer.class);var second=opportunities.detect(OWNER);assertThat(second).isEqualTo(first);assertThat(jdbc.queryForObject("SELECT count(*) FROM loanops.opportunity_event",Integer.class)).isEqualTo(afterFirst);}
 @Test void payloadIsEncryptedAndImmutable(){scenarios.createHome(OWNER,ScenarioExamples.golden(twins.latest(OWNER).financialSnapshotId()));var event=opportunities.detect(OWNER).getFirst();String payload=jdbc.queryForObject("SELECT payload_ciphertext FROM loanops.opportunity_event WHERE id=?",String.class,event.opportunityEventId());assertThat(payload).doesNotContain("MONTHLY_FREE_CASHFLOW","-1789443","DEBT_SERVICE_BURDEN");assertThatThrownBy(()->jdbc.update("DELETE FROM loanops.opportunity_event WHERE id=?",event.opportunityEventId())).isInstanceOf(org.springframework.dao.DataAccessException.class);}
 @Test void apiReturnsActiveEventsWithEvidenceAndRuleVersion()throws Exception{scenarios.createHome(OWNER,ScenarioExamples.golden(twins.latest(OWNER).financialSnapshotId()));http.perform(get("/api/v1/opportunities")).andExpect(status().isOk()).andExpect(jsonPath("$[0].ruleVersion").value("OPPORTUNITY_V1")).andExpect(jsonPath("$[0].evidence.metric").exists()).andExpect(jsonPath("$[0].status").value("ACTIVE"));}
}
